"""Offline context collection and ranking, promoted from the verified POC."""

import argparse
import json
import re
import sqlite3
import subprocess
import time
import unicodedata
from contextlib import closing
from itertools import islice
from pathlib import Path

TOKEN = re.compile(r"[A-Za-zА-Яа-яЁё][A-Za-zА-Яа-яЁё0-9+#-]{1,39}")
COMPOUND = re.compile(r"\b[A-Z]{2,8} [0-9]{1,4}\b")
SENSITIVE = re.compile(
    r"https?://|\S+@\S+|(?:password|passwd|secret|token|api[_-]?key)\s*[:=]"
    r"|\b(?:sk-|ghp_|github_pat_)[\w-]+|-----BEGIN",
    re.IGNORECASE,
)
STOP = {
    "the", "and", "for", "with", "from", "this", "that", "untitled", "new", "file",
    "folder", "main", "master", "windows", "microsoft", "edge", "chrome", "readme",
    "src", "tests", "venv", "node_modules", "для", "или", "это", "как", "что", "файл",
    "папка", "новый", "python", "exe", "dll", "cmd", "yaml", "json", "md",
}
WEIGHTS = {"active": 10, "clipboard": 6, "project": 8, "branch": 8, "file": 3}


def candidates(text):
    """Keep source spelling; reject common prose and obvious credential lines."""
    result = {}
    for line in unicodedata.normalize("NFKC", text[:4096]).splitlines():
        if SENSITIVE.search(line):
            continue
        phrases = COMPOUND.findall(line)
        for phrase in phrases:
            line = line.replace(phrase, " ")
        for term in phrases + TOKEN.findall(line):
            if term.casefold() in STOP or len(term) > 40:
                continue
            if not (term[0].isupper() or re.search(r"[A-Z+#]", term[1:])):
                continue
            result.setdefault(term.casefold(), term)
    return list(result.values())[:100]


def collect(project):
    """Foreground title (including active tab), clipboard, shallow names and Git."""
    items = []
    status = {}
    try:
        import win32gui

        title = win32gui.GetWindowText(win32gui.GetForegroundWindow())
        items.append(("active", title))
        status["active"] = "ok"
    except Exception as exc:  # noqa: BLE001 - optional context must fail open
        status["active"] = type(exc).__name__
    try:
        import win32clipboard
        import win32con

        win32clipboard.OpenClipboard()
        try:
            if win32clipboard.IsClipboardFormatAvailable(win32con.CF_UNICODETEXT):
                items.append(("clipboard", win32clipboard.GetClipboardData(
                    win32con.CF_UNICODETEXT)[:4096]))
            status["clipboard"] = "ok"
        finally:
            win32clipboard.CloseClipboard()
    except Exception as exc:  # noqa: BLE001 - clipboard contention must not block STT
        status["clipboard"] = type(exc).__name__
    if project is None:
        return items, status
    items.append(("project", project.name))
    try:
        for entry in islice(project.iterdir(), 200):
            if not entry.name.startswith("."):
                items.append(("file", entry.stem))
        status["files"] = "ok"
    except OSError as exc:
        status["files"] = type(exc).__name__
    try:
        result = subprocess.run(
            ["git", "-C", str(project), "branch", "--show-current"],
            capture_output=True, text=True, timeout=1, check=False,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
        if result.returncode == 0:
            items.append(("branch", result.stdout.strip()))
        status["git"] = "ok" if result.returncode == 0 else "not a repository"
    except (OSError, subprocess.TimeoutExpired) as exc:
        status["git"] = type(exc).__name__
    return items, status


def rank(db_path, project, items, now=None, ttl=900, limit=30):
    """Project-isolated TTL cache. Repeated polling does not boost frequency."""
    now = time.time() if now is None else now
    scope = str(project.resolve()).casefold() if project is not None else "(desktop)"
    with closing(sqlite3.connect(db_path, timeout=0.2)) as db, db:
        db.execute("""CREATE TABLE IF NOT EXISTS terms (
            scope TEXT, source TEXT, key TEXT, spelling TEXT,
            weight REAL, seen REAL, expires REAL,
            PRIMARY KEY(scope, source, key))""")
        db.execute("DELETE FROM terms WHERE expires <= ?", (now,))
        for source, text in items:
            for term in candidates(text):
                db.execute("""INSERT INTO terms VALUES (?, ?, ?, ?, ?, ?, ?)
                    ON CONFLICT(scope, source, key) DO UPDATE SET
                    spelling=excluded.spelling, weight=excluded.weight,
                    seen=excluded.seen, expires=excluded.expires""",
                           (scope, source, term.casefold(), term,
                            WEIGHTS[source], now, now + ttl))
        rows = db.execute("""SELECT key, spelling, weight, seen, expires
            FROM terms WHERE scope=? AND expires>?""", (scope, now)).fetchall()
    scores = {}
    for key, spelling, weight, seen, expires in rows:
        score = weight * max(0, (expires - now) / (expires - seen))
        if key not in scores or score > scores[key][0]:
            scores[key] = (score, spelling)
    return [value[1] for _, value in sorted(
        scores.items(), key=lambda item: (-item[1][0], item[0])
    )[:max(0, min(limit, 30))]]


def merge(permanent, runtime):
    """Preserve existing hotwords verbatim and append unique runtime terms."""
    seen = {term.strip().casefold() for term in (permanent or "").split(",")}
    extra = []
    for term in runtime:
        if term.casefold() not in seen:
            seen.add(term.casefold())
            extra.append(term)
    return ", ".join(([permanent] if permanent else []) + extra) or None


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--project", type=Path, required=True)
    parser.add_argument("--db", type=Path, default=Path("vocabulary.db"))
    args = parser.parse_args()
    started = time.perf_counter()
    items, status = collect(args.project.resolve())
    terms = rank(args.db, args.project, items)
    # Do not print clipboard/title contents or extracted private terms.
    print(json.dumps({"sources": status, "runtime_count": len(terms),
                      "elapsed_ms": round((time.perf_counter() - started) * 1000)},
                     ensure_ascii=False))


if __name__ == "__main__":
    main()
